// oxlint-disable-next-line import/no-nodejs-modules -- Recompile the kept content source rather than trusting generated bytes.
import { readFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import { generateQaraModule } from '../../../src/shards/nalati-grasslands/generators/qara';
import { QARA_MODULE } from '../../../src/shards/nalati-grasslands/runtime/qaraBrain';

it('regenerates the cached module byte-for-byte from the kept SDK-driven TypeScript recipe', async () => {
  const source = readFileSync('src/shards/nalati-grasslands/behaviour/qara.as', 'utf8');
  expect(await generateQaraModule(source)).toEqual(QARA_MODULE);
  expect(QARA_MODULE.notice).toContain('DO NOT EDIT');
});
